mapper.select:
SELECT chunk_id AS chunkId,
       doc_id AS docId,
       tenant_id AS tenantId,
       version,
       chunk_index AS chunkIndex,
       content,
       1 - (embedding <=> #{embedding,typeHandler=com.docplatform.vector.mybatis.PGvectorTypeHandler}) AS score
FROM vector_idx.document_chunk
WHERE tenant_id = #{tenantId}

    AND doc_id IN

        #{id}


ORDER BY embedding <=> #{embedding,typeHandler=com.docplatform.vector.mybatis.PGvectorTypeHandler}
LIMIT #{topK}
